package com.quizmaster.dao;
import com.quizmaster.model.*;import com.quizmaster.util.*;import java.sql.*;import java.util.*;
public class AttemptDAO {
 public record ResultRow(long attemptId,String student,String quiz,double score,int maxScore,String status,Timestamp date){public long getAttemptId(){return attemptId;}public String getStudent(){return student;}public String getQuiz(){return quiz;}public double getScore(){return score;}public int getMaxScore(){return maxScore;}public String getStatus(){return status;}public Timestamp getDate(){return date;}}
 public List<ResultRow> history(Long user,Long quiz)throws SQLException{String sql="SELECT a.attempt_id,u.full_name,q.title,a.score,q.total_marks,a.attempt_status,a.started_at FROM attempts a JOIN users u ON a.user_id=u.user_id JOIN quizzes q ON a.quiz_id=q.quiz_id WHERE (? IS NULL OR a.user_id=?) AND (? IS NULL OR a.quiz_id=?) ORDER BY a.started_at DESC";List<ResultRow> out=new ArrayList<>();try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement(sql)){if(user==null){p.setNull(1,Types.NUMERIC);p.setNull(2,Types.NUMERIC);}else{p.setLong(1,user);p.setLong(2,user);}if(quiz==null){p.setNull(3,Types.NUMERIC);p.setNull(4,Types.NUMERIC);}else{p.setLong(3,quiz);p.setLong(4,quiz);}try(ResultSet r=p.executeQuery()){while(r.next())out.add(new ResultRow(r.getLong(1),r.getString(2),r.getString(3),r.getDouble(4),r.getInt(5),r.getString(6),r.getTimestamp(7)));}}return out;}
 public Attempt getForUser(long attempt,long user)throws SQLException{try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement("SELECT * FROM attempts WHERE attempt_id=? AND user_id=?")){p.setLong(1,attempt);p.setLong(2,user);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
 private Attempt map(ResultSet r)throws SQLException{return new Attempt(r.getLong("attempt_id"),r.getLong("user_id"),r.getLong("quiz_id"),r.getTimestamp("started_at"),r.getTimestamp("submitted_at"),r.getDouble("score"),r.getString("attempt_status"));}
 public Attempt start(long user,long quiz)throws SQLException{try(Connection c=DBConnection.open()){try(PreparedStatement p=c.prepareStatement("INSERT INTO attempts(user_id,quiz_id) VALUES(?,?)")){p.setLong(1,user);p.setLong(2,quiz);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("SELECT * FROM attempts WHERE user_id=? AND quiz_id=?")){p.setLong(1,user);p.setLong(2,quiz);try(ResultSet r=p.executeQuery()){if(r.next())return map(r);}}}throw new SQLException("Unable to create attempt");}
 public record Submission(String status,double score,int right,int wrong,int max){}
 public Submission submit(long attemptId,long user,Map<Long,String> submitted,int graceSeconds)throws SQLException{
  try(Connection c=DBConnection.open()){c.setAutoCommit(false);try{
   long quizId;int duration,total;Timestamp started;String state;
   try(PreparedStatement p=c.prepareStatement("SELECT a.quiz_id,a.started_at,a.attempt_status,q.duration_minutes,q.total_marks FROM attempts a JOIN quizzes q ON a.quiz_id=q.quiz_id WHERE a.attempt_id=? AND a.user_id=? FOR UPDATE")){p.setLong(1,attemptId);p.setLong(2,user);try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Attempt not found");quizId=r.getLong(1);started=r.getTimestamp(2);state=r.getString(3);duration=r.getInt(4);total=r.getInt(5);}}
   if(!"IN_PROGRESS".equals(state))throw new IllegalArgumentException("Attempt already finished");
   // Use database clock, not browser or application time.
   Timestamp now;try(PreparedStatement p=c.prepareStatement("SELECT SYSTIMESTAMP FROM dual");ResultSet r=p.executeQuery()){r.next();now=r.getTimestamp(1);}
   boolean expired=now.toInstant().isAfter(started.toInstant().plusSeconds(duration*60L+graceSeconds));
   List<Question> questions=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT * FROM questions WHERE quiz_id=?")){p.setLong(1,quizId);try(ResultSet r=p.executeQuery()){while(r.next())questions.add(new Question(r.getLong("question_id"),quizId,r.getString("question_text"),r.getString("option_a"),r.getString("option_b"),r.getString("option_c"),r.getString("option_d"),r.getString("correct_option"),r.getInt("marks")));}}
   int right=0,wrong=0,points=0,possible=0;for(Question q:questions){possible+=q.marks();String selection=expired?null:submitted.get(q.id());if(selection!=null&&!List.of("A","B","C","D").contains(selection))selection=null;boolean correct=q.correct().equals(selection);if(correct){right++;points+=q.marks();}else wrong++;try(PreparedStatement p=c.prepareStatement("INSERT INTO answers(attempt_id,question_id,selected_option,is_correct) VALUES(?,?,?,?)")){p.setLong(1,attemptId);p.setLong(2,q.id());p.setString(3,selection);p.setInt(4,correct?1:0);p.executeUpdate();}}
   double score=expired||possible==0?0:Math.round(100.0*points*total/possible)/100.0;
   try(PreparedStatement p=c.prepareStatement("UPDATE attempts SET submitted_at=SYSTIMESTAMP,score=?,attempt_status=? WHERE attempt_id=?")){p.setDouble(1,score);p.setString(2,expired?"EXPIRED":"SUBMITTED");p.setLong(3,attemptId);p.executeUpdate();}c.commit();return new Submission(expired?"EXPIRED":"SUBMITTED",score,expired?0:right,expired?questions.size():wrong,total);
  }catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;if(e instanceof RuntimeException r)throw r;throw new SQLException(e);}finally{c.setAutoCommit(true);}}
 }
 public List<Map<String,Object>> details(long attemptId,long user)throws SQLException{List<Map<String,Object>> out=new ArrayList<>();String sql="SELECT q.question_text,q.correct_option,a.selected_option,a.is_correct FROM answers a JOIN questions q ON a.question_id=q.question_id JOIN attempts t ON t.attempt_id=a.attempt_id WHERE a.attempt_id=? AND t.user_id=? ORDER BY q.question_id";try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement(sql)){p.setLong(1,attemptId);p.setLong(2,user);try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object> m=new HashMap<>();m.put("text",r.getString(1));m.put("correct",r.getString(2));m.put("selected",r.getString(3));m.put("right",r.getInt(4)==1);out.add(m);}}}return out;}
}
